import {ToolRegistry} from './registry.js';
import Ajv from 'ajv';
import {jest} from '@jest/globals';
import {setLogger, type Logger} from '../../shared/logger.js';

const locationInputSchema = {
  type: 'object',
  properties: {location: {type: 'string'}},
  required: ['location'],
};

describe('ToolRegistry', () => {
  afterEach(() => {
    setLogger();
    jest.restoreAllMocks();
  });

  it('rejects missing required input', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: locationInputSchema,
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('weather', {});

    expect({
      namesRequiredProperty: /location.*required|required.*location/i.test(response.result),
      executorCalls,
    }).toEqual({namesRequiredProperty: true, executorCalls: 0});
  });

  it('rejects a wrong type without exposing its value in the response or logs', async () => {
    const registry = new ToolRegistry();
    const identifyingValue = 'private-user@example.com';
    let executorCalls = 0;
    const logLines: string[] = [];
    const testLogger: Logger = {
      debug: (_category, message, fields) => logLines.push(`${message} ${JSON.stringify(fields)}`),
      info: (_category, message, fields) => logLines.push(`${message} ${JSON.stringify(fields)}`),
      warn: (_category, message, fields) => logLines.push(`${message} ${JSON.stringify(fields)}`),
      error: (_category, message, fields) => logLines.push(`${message} ${JSON.stringify(fields)}`),
    };
    setLogger(testLogger);
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'number'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('weather', {location: identifyingValue as unknown as number});
    expect({
      namesPath: response.result.includes('location'),
      namesExpectedType: response.result.includes('number'),
      hidesValueFromResult: !response.result.includes(identifyingValue),
      hidesValueFromLogs: !logLines.join('\n').includes(identifyingValue),
      executorCalls,
    }).toEqual({
      namesPath: true,
      namesExpectedType: true,
      hidesValueFromResult: true,
      hidesValueFromLogs: true,
      executorCalls: 0,
    });
  });

  it('rejects an enum value and names the field and constraint', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'set_mode',
        description: 'Set operating mode',
        inputSchema: {
          type: 'object',
          properties: {mode: {type: 'string', enum: ['safe', 'fast']}},
          required: ['mode'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'set';
      }
    );

    const response = await registry.execute('set_mode', {mode: 'unsafe'});

    expect({
      executorCalls,
      namesField: response.result.includes('mode'),
      namesConstraint: /enum|allowed value/i.test(response.result),
    }).toEqual({executorCalls: 0, namesField: true, namesConstraint: true});
  });

  it('passes valid input with extra properties to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Berlin', units: 'celsius'};
    let executorCalls = 0;
    let passedInput: Record<string, unknown> | undefined;
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: locationInputSchema,
      },
      async receivedInput => {
        executorCalls += 1;
        passedInput = receivedInput;
        return 'sunny';
      }
    );

    await registry.execute('weather', input);

    expect({calls: executorCalls, input: passedInput}).toEqual({calls: 1, input});
  });

  it('validates each function-valued definition against its current schema', async () => {
    const registry = new ToolRegistry();
    const schemas = [
      {type: 'object', properties: {city: {type: 'string'}}, required: ['city']},
      {type: 'object', properties: {postalCode: {type: 'number'}}, required: ['postalCode']},
    ];
    let definitionCalls = 0;
    let executorCalls = 0;
    registry.register(
      () => ({
        name: 'dynamic_weather',
        description: 'Weather with a changing input schema',
        inputSchema: schemas[definitionCalls++ === 2 ? 1 : 0],
      }),
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const first = await registry.execute('dynamic_weather', {city: 'Berlin'});
    const second = await registry.execute('dynamic_weather', {postalCode: '10115'});

    expect({
      firstAccepted: first.result === 'sunny',
      secondNamesPath: second.result.includes('postalCode'),
      secondNamesExpectedType: second.result.includes('number'),
      executorCalls,
    }).toEqual({
      firstAccepted: true,
      secondNamesPath: true,
      secondNamesExpectedType: true,
      executorCalls: 1,
    });
  });

  it('compiles a static schema once across repeated executions', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    registry.register(
      {name: 'weather', description: 'Get weather', inputSchema: locationInputSchema},
      async () => 'sunny'
    );
    expect(compile).toHaveBeenCalledTimes(1);

    for (let call = 0; call < 10; call += 1) {
      await registry.execute('weather', {location: 'Berlin'});
    }

    expect(compile).toHaveBeenCalledTimes(1);
  });
});
# Lore test-command interface (lore_list_tests / lore_run_test).
# Written for this repo's Jest suite rather than adapted from the Vitest
# equivalent for a Vitest suite: the report shapes happen to match, but the
# invocations do not.
- id: hal-engine-jest
  name: HAL Engine Jest suite
  cwd: .
  description: >-
    The ts-jest unit suite over src/ and scripts/ (jest.config.js roots), run
    on every pull request in .github/workflows/ci.yml as the "Test" step.
    Selectors are "<repo-relative-file>::<full test name>" as emitted by the
    list command. Jest has no dry-run, so the list command executes the suite
    once with --json and derives every name from the report; it deliberately
    tolerates a red suite, since listing must not depend on the tests passing.
    The run command selects one test with --runTestsByPath plus an anchored,
    regex-escaped -t, and treats a selector that matches nothing as a failure
    rather than a green run of an empty suite. Neither command builds first:
    no test here reads dist/.
  list: node scripts/lore-list-tests.mjs
  run: node scripts/lore-run-test.mjs "{selector}"
  coverage_format: lcov
